import{_ as i,c as o,o as a,ae as t}from"./chunks/framework.DMK_uHmU.js";const h=JSON.parse('{"title":"User Profile Personal Information Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-personal.md","filePath":"Administration/Manage/Users/user-personal.md"}'),r={name:"Administration/Manage/Users/user-personal.md"};function n(l,e,s,d,u,p){return a(),o("div",null,e[0]||(e[0]=[t('<h1 id="user-profile-personal-information-guide" tabindex="-1">User Profile Personal Information Guide <a class="header-anchor" href="#user-profile-personal-information-guide" aria-label="Permalink to &quot;User Profile Personal Information Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The User Profile Personal Information component allows administrators to record and manage additional details about users beyond basic account information. This supplementary data includes professional details and address information that may be useful for organizational purposes.</p><h2 id="accessing-personal-information" tabindex="-1">Accessing Personal Information <a class="header-anchor" href="#accessing-personal-information" aria-label="Permalink to &quot;Accessing Personal Information&quot;">​</a></h2><p>The Personal Information component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to a user profile page (<code>/user/profile/[user_id]</code>)</li><li>Click on the &quot;Personal Information&quot; tab in the left navigation menu</li></ol><h2 id="personal-information-interface-overview" tabindex="-1">Personal Information Interface Overview <a class="header-anchor" href="#personal-information-interface-overview" aria-label="Permalink to &quot;Personal Information Interface Overview&quot;">​</a></h2><p>The Personal Information interface displays a form with multiple sections organized in a responsive grid layout. Each section contains related fields with clear labels and appropriate input controls.</p><p>The header area includes:</p><ul><li>An ID card icon indicating personal details</li><li>A &quot;Personal Information&quot; title</li><li>A brief description: &quot;Optional personal information can be added here&quot;</li></ul><p>The form is divided into three main sections:</p><ol><li>Professional Details</li><li>Work Address</li><li>Home Address</li></ol><h2 id="available-information-fields" tabindex="-1">Available Information Fields <a class="header-anchor" href="#available-information-fields" aria-label="Permalink to &quot;Available Information Fields&quot;">​</a></h2><h3 id="professional-details" tabindex="-1">Professional Details <a class="header-anchor" href="#professional-details" aria-label="Permalink to &quot;Professional Details&quot;">​</a></h3><p>These fields capture information related to the user&#39;s role within the organization:</p><p><strong>Job Title</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the user&#39;s official position or title</li><li>Example: &quot;Senior Developer&quot;, &quot;Marketing Manager&quot;, &quot;Regional Director&quot;</li><li>This field helps identify the user&#39;s role within the organizational hierarchy</li></ul><p><strong>Department</strong></p><ul><li>Type: Text field</li><li>Purpose: Records which department or business unit the user belongs to</li><li>Example: &quot;Engineering&quot;, &quot;Marketing&quot;, &quot;Human Resources&quot;, &quot;Finance&quot;</li><li>This field enables filtering and grouping users by department</li></ul><p><strong>Reports To</strong></p><ul><li>Type: Dropdown selection</li><li>Purpose: Identifies the user&#39;s direct supervisor or manager</li><li>Options: List of potential managers in the system</li><li>This field helps establish organizational reporting structures</li></ul><h3 id="work-address" tabindex="-1">Work Address <a class="header-anchor" href="#work-address" aria-label="Permalink to &quot;Work Address&quot;">​</a></h3><p>This section captures the user&#39;s work location:</p><p><strong>Street Address</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the street number, name, and any unit/suite information</li><li>Example: &quot;123 Business Park Drive, Suite 200&quot;</li></ul><p><strong>City</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the city name</li><li>Example: &quot;San Francisco&quot;</li></ul><p><strong>State</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the state or province</li><li>Example: &quot;CA&quot;, &quot;New York&quot;, &quot;Ontario&quot;</li></ul><p><strong>Zip/Postal Code</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the postal code</li><li>Example: &quot;94105&quot;, &quot;M5V 2H1&quot;</li></ul><h3 id="home-address" tabindex="-1">Home Address <a class="header-anchor" href="#home-address" aria-label="Permalink to &quot;Home Address&quot;">​</a></h3><p>This section captures the user&#39;s personal residence information:</p><p><strong>Street Address</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the user&#39;s home street address</li><li>Example: &quot;456 Residential Lane, Apt 7B&quot;</li></ul><p><strong>City</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the city name</li><li>Example: &quot;Chicago&quot;</li></ul><p><strong>State</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the state or province</li><li>Example: &quot;IL&quot;, &quot;Texas&quot;, &quot;British Columbia&quot;</li></ul><p><strong>Zip/Postal Code</strong></p><ul><li>Type: Text field</li><li>Purpose: Records the postal code</li><li>Example: &quot;60601&quot;, &quot;V6B 2G9&quot;</li></ul><h2 id="managing-personal-information" tabindex="-1">Managing Personal Information <a class="header-anchor" href="#managing-personal-information" aria-label="Permalink to &quot;Managing Personal Information&quot;">​</a></h2><h3 id="adding-information" tabindex="-1">Adding Information <a class="header-anchor" href="#adding-information" aria-label="Permalink to &quot;Adding Information&quot;">​</a></h3><ol><li>Navigate to the user&#39;s Personal Information tab</li><li>Fill in the desired fields</li><li>Personal information is saved when the main user profile form is submitted</li></ol><h3 id="updating-information" tabindex="-1">Updating Information <a class="header-anchor" href="#updating-information" aria-label="Permalink to &quot;Updating Information&quot;">​</a></h3><ol><li>Navigate to the user&#39;s Personal Information tab</li><li>Modify the fields as needed</li><li>Changes are saved when the main user profile form is submitted</li></ol><h3 id="clearing-information" tabindex="-1">Clearing Information <a class="header-anchor" href="#clearing-information" aria-label="Permalink to &quot;Clearing Information&quot;">​</a></h3><ol><li>Navigate to the user&#39;s Personal Information tab</li><li>Delete the content from fields you wish to clear</li><li>Changes are saved when the main user profile form is submitted</li></ol><h2 id="data-usage-and-privacy" tabindex="-1">Data Usage and Privacy <a class="header-anchor" href="#data-usage-and-privacy" aria-label="Permalink to &quot;Data Usage and Privacy&quot;">​</a></h2><p>Personal information collected in this section should be handled according to your organization&#39;s data privacy policies:</p><ol><li><strong>Purpose Limitation</strong>: Only collect information necessary for legitimate business purposes</li><li><strong>Access Control</strong>: Limit who can view personal address information</li><li><strong>Data Minimization</strong>: Consider whether all fields are necessary for your organization</li><li><strong>Legal Compliance</strong>: Ensure collection complies with applicable privacy laws (GDPR, CCPA, etc.)</li><li><strong>Retention</strong>: Define and follow policies for how long this information is kept</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Complete Professional Details</strong></p><ul><li>Always complete Job Title and Department fields for organizational clarity</li><li>Use consistent naming for departments across all users</li><li>Maintain an accurate reporting structure through the &quot;Reports To&quot; field</li></ul></li><li><p><strong>Address Information</strong></p><ul><li>Work address should be recorded for all employees for emergency contact purposes</li><li>Home address information should be collected only when necessary for: <ul><li>Payroll/tax purposes</li><li>Shipping company equipment</li><li>Emergency contact situations</li></ul></li></ul></li><li><p><strong>Data Standardization</strong></p><ul><li>Use consistent formats for addresses</li><li>Consider using address validation for postal codes</li><li>Standardize state/province abbreviations (e.g., &quot;CA&quot; vs &quot;California&quot;)</li></ul></li><li><p><strong>Organizational Hierarchy</strong></p><ul><li>Keep the &quot;Reports To&quot; field updated when management changes occur</li><li>This information may be used for automated approval workflows</li><li>Accurate reporting structures enable better organizational analytics</li></ul></li><li><p><strong>Maintenance</strong></p><ul><li>Review personal information periodically for accuracy</li><li>Update information when users change roles or locations</li><li>Remove outdated information to maintain data quality</li></ul></li></ol><hr><p>Note that all fields in the Personal Information section are optional. However, completing them provides valuable context for user management and organizational structure visualization.</p>',57)]))}const m=i(r,[["render",n]]);export{h as __pageData,m as default};
